    def __init__(self):
        super().__init__()
        self.regs = {
            0x1: 0x0000,  # DAC_RD
            0x2: 0x0000,  # ADC_SEQ
            0x3: 0x0000,  # GEN_CTRL_REG
            0x4: 0x0000,  # ADC_CONFIG
            0x5: 0x0000,  # DAC_CONFIG
            0x6: 0x00FF,  # PULLDWN_CONFIG
            0xF: 0x0000   # SW_RESET
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address {addr}")

        value = self.regs[addr]

        if nbytes == 1:
            return (value >> 8) & 0xFF

        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address {addr}")

        if addr == 0xF:  # SW_RESET
            if data == 0x5AC:
                for reg_addr, reset_value in self.regs.items():
                    self.regs[reg_addr] = reset_value
            return

        if nbytes == 1:
            current_value = self.regs[addr]
            data = (current_value & 0x00FF) | (data << 8)

        self.regs[addr] = data & 0xFFFF

