class AD5592R_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        self.regs = {
            0x1: 0x0000,  # DAC_RD
            0x2: 0x0000,  # ADC_SEQ
            0x3: 0x0000,  # GEN_CTRL_REG
            0x4: 0x0000,  # ADC_CONFIG
            0x5: 0x0000,  # DAC_CONFIG
            0x6: 0x00FF,  # PULLDWN_CONFIG
            0xF: 0x0000,  # SW_RESET
